import { useEffect, useState } from "react";

const API = "http://localhost:5000/students";

export default function Students() {
  const [students, setStudents] = useState([]);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [department, setDepartment] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState("");

  // Load students
  const loadStudents = async () => {
  
  };

  useEffect(() => {
    loadStudents();
  }, []);

  const resetForm = () => {
    setName("");
    setEmail("");
    setDepartment("");
    setEditingId(null);
    setError("");
  };

  // Add or Update
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    const payload = { name, email, department };

    try {
      const res = await fetch(editingId ? `${API}/${editingId}` : API, {
        method: editingId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Action failed");
        return;
      }

      await loadStudents();
      resetForm();
    } catch (e) {
      setError("Network error");
    }
  };

  // Start Edit
  const startEdit = (stu) => {
    setEditingId(stu._id);
    setName(stu.name);
    setEmail(stu.email);
    setDepartment(stu.department);
    setError("");
  };

  // Delete
  const handleDelete = async (id) => {
    if (!window.confirm("Delete this student?")) return;
    try {
      const res = await fetch(`${API}/${id}`, { method: "DELETE" });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Delete failed");
        return;
      }
      setStudents((prev) => prev.filter((s) => s._id !== id));
    } catch {
      setError("Network error");
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-3">Students</h2>

      {error && <div className="alert alert-danger">{error}</div>}

      <form onSubmit={handleSubmit} className="row g-2 mb-4">
        <div className="col-md-3">
          <input
            className="form-control"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </div>
        <div className="col-md-3">
          <input
            className="form-control"
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </div>
        <div className="col-md-3">
          <input
            className="form-control"
            placeholder="Department"
            value={department}
            onChange={(e) => setDepartment(e.target.value)}
            required
          />
        </div>
        <div className="col-md-3 d-flex gap-2">
          <button type="submit" className="btn btn-primary">
            {editingId ? "Update" : "Add Student"}
          </button>
          {editingId && (
            <button type="button" className="btn btn-secondary" onClick={resetForm}>
              Cancel
            </button>
          )}
        </div>
      </form>

      <table className="table table-striped">
        <thead>
          <tr>
            <th>#</th>
            <th>Student ID</th>
            <th>Name</th>
            <th>Email</th>
            <th>Department</th>
            <th style={{ width: 160 }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {students.map((s, idx) => (
            <tr key={s._id}>
              <td>{idx + 1}</td>
              <td>{s._id}</td>
              <td>{s.name}</td>
              <td>{s.email}</td>
              <td>{s.department}</td>
              <td>
                <button className="btn btn-sm btn-outline-primary me-2" onClick={() => startEdit(s)}>
                  Edit
                </button>
                <button className="btn btn-sm btn-outline-danger" onClick={() => handleDelete(s._id)}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
          {students.length === 0 && (
            <tr>
              <td colSpan="6" className="text-center text-muted">
                No students yet
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
